import { loadConfig, requireNamedDatabase } from '../../config/env.js';
import { createLogger } from '../../config/logger.js';
import {
  connectDatabase,
  disconnectDatabase,
} from '../../services/database.js';
import { initializeAuthIndexes, User } from './models.js';
import { normalizedEmail } from './schemas.js';

async function bootstrap() {
  const [flag, target, confirmFlag, confirmation, ...rest] =
    process.argv.slice(2);
  const email = normalizedEmail.safeParse(target);
  if (
    flag !== '--email' ||
    confirmFlag !== '--confirm' ||
    !email.success ||
    email.data !== confirmation?.trim().toLowerCase() ||
    rest.length
  ) {
    throw new Error(
      'Usage: npm run auth:bootstrap-admin -w @fdfs/backend -- --email <email> --confirm <email>',
    );
  }

  const config = loadConfig();
  requireNamedDatabase(config.MONGODB_URI);
  const logger = createLogger(config.LOG_LEVEL);
  try {
    await connectDatabase(config.MONGODB_URI, logger);
    await initializeAuthIndexes();
    if (
      await User.exists({
        $or: [
          { roles: { $in: ['admin', 'super_admin'] } },
          { bootstrapAdmin: true },
        ],
      })
    ) {
      throw new Error(
        'Administrator bootstrap has already been used or an administrator exists.',
      );
    }
    const user = await User.findOneAndUpdate(
      {
        email: email.data,
        status: 'active',
        emailVerifiedAt: { $type: 'date' },
      },
      {
        $addToSet: { roles: 'admin' },
        $set: { bootstrapAdmin: true },
        $inc: { authVersion: 1 },
      },
    );
    if (!user)
      throw new Error('No matching active, verified account was found.');
    console.log(
      'Initial administrator role assigned. The account must sign in again.',
    );
  } catch (error) {
    if (error.code === 11000)
      throw new Error('Administrator bootstrap was already completed.', {
        cause: error,
      });
    if (
      [
        'MongoServerError',
        'MongooseServerSelectionError',
        'MongoNetworkError',
        'MongoParseError',
      ].includes(error.name)
    ) {
      throw new Error(
        'Administrator bootstrap could not access the configured database.',
        { cause: error },
      );
    }
    throw error;
  } finally {
    await disconnectDatabase();
  }
}

bootstrap().catch((error) => {
  // Only display messages generated by this command or the configuration loader.
  const safe =
    error.message.startsWith('Usage:') ||
    /^(Administrator bootstrap|No matching|Invalid configuration|Unable to read|Specify the intended database)/.test(
      error.message,
    );
  console.error(safe ? error.message : 'Administrator bootstrap failed.');
  process.exitCode = 1;
});
